import ReactDOM from "react-dom/client";
import { App } from "./App";
import "./styles.css";

const container = document.getElementById("root");
if (container === null) throw new Error("No se encontró el contenedor de la aplicación");

// Esta etapa registra únicamente la pantalla de login. `/trading` es el destino
// contractual de la navegación exitosa, pero su pantalla se implementa en otra etapa.
const isLoginLocation = window.location.pathname === "/" || window.location.pathname === "/login";
ReactDOM.createRoot(container).render(isLoginLocation ? <App /> : null);

