async (page) => {
  const reqs = [];
  page.on('request', r => reqs.push({type: 'req', method: r.method(), url: r.url()}));
  page.on('requestfailed', r => reqs.push({type: 'fail', method: r.method(), url: r.url(), err: r.failure() && r.failure().errorText}));
  page.on('response', async r => {
    let body = null;
    try { body = await r.text(); } catch {}
    reqs.push({type: 'res', method: r.request().method(), url: r.url(), status: r.status(), body: body && body.slice(0, 400)});
  });
  await page.getByRole('button', { name: 'Ingresar' }).click();
  try {
    await page.waitForURL('**/trading', { timeout: 8000 });
  } catch (e) {
    return { nav: false, url: page.url(), reqs, html: (await page.locator('.notice, [role=alert]').allTextContents()).slice(0,5), err: String(e).slice(0,200) };
  }
  return { nav: true, url: page.url(), reqs, title: await page.title(), bodyText: await page.evaluate(() => document.body.innerText).then(t => t.slice(0,500)) };
}

