async (page) => {
  const debug = await page.evaluate(() => {
    const email = document.querySelector('#email');
    const password = document.querySelector('#password');
    const btn = document.querySelector('button[type=submit]');
    return {
      emailValue: email && email.value,
      passwordValue: password && password.value,
      btnDisabled: btn && btn.disabled,
      btnBusy: btn && btn.getAttribute('aria-busy'),
      btnText: btn && btn.innerText,
    };
  });
  await page.evaluate(() => {
    window.__fetches = [];
    const orig = window.fetch;
    window.fetch = async function() {
      const args = [arguments[0], arguments[1] && { method: arguments[1].method, headers: arguments[1].headers, body: arguments[1].body }];
      window.__fetches.push({stage:'start', args});
      try {
        const res = await orig.apply(this, arguments);
        window.__fetches.push({stage:'done', status: res.status, url: res.url});
        return res;
      } catch (e) {
        window.__fetches.push({stage:'err', error: String(e)});
        throw e;
      }
    };
    const form = document.querySelector('form');
    form.addEventListener('submit', (ev) => {
      window.__submitFired = { defaultPrevented: ev.defaultPrevented, time: Date.now() };
    }, true);
  });
  await page.getByRole('button', { name: 'Ingresar' }).click();
  await page.waitForTimeout(1500);
  const after = await page.evaluate(() => ({
    fetches: window.__fetches,
    submitFired: window.__submitFired || null,
    notice: document.querySelector('[role=alert], .notice') && document.querySelector('[role=alert], .notice').textContent,
    url: location.href,
    btnDisabled: document.querySelector('button[type=submit]') && document.querySelector('button[type=submit]').disabled,
  }));
  return { debug, after };
}

