  await page.locator('#password').fill('EvalWeb123!');
  await page.locator('button[type=submit]').click();
  try {
    await page.waitForURL('**/trading', { timeout: 15000 });
  } catch (e) {
    const ui = await page.evaluate(() => ({
      url: location.href,
      notices: Array.from(document.querySelectorAll('[role=alert],[role=status],.notice')).map(el => el.textContent),
      btn: document.querySelector('button[type=submit]') && document.querySelector('button[type=submit]').innerText,
    }));
    return { loginOk: false, ui, err: String(e).slice(0,200) };
  }
  const session = await page.evaluate(() => localStorage.getItem('exchange.session.v1'));
  const token = JSON.parse(session).token;
  const logout = await page.evaluate(async (t) => {
    const res = await fetch('http://127.0.0.1:3203/api/v1/auth/logout', {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + t },
    });
    return { status: res.status, body: await res.text() };
  }, token);
  const reqs = [];
  page.on('response', async (r) => {
    if (r.url().includes('/api/v1/me') || r.url().includes('auth')) {
      let body = '';
      try { body = await r.text(); } catch {}
      reqs.push({ url: r.url(), status: r.status(), body: body.slice(0, 300), auth: r.request().headers()['authorization'] });
    }
  });
