    localStorage: { ...localStorage },
    sessionStorage: { ...sessionStorage },
    hasForm: !!document.querySelector('#email'),
  }));
  await page.screenshot({ path: 'evidencia/AT-10-01-07-1.png', scale: 'css' });
  return { loginOk: true, logout, tokenLen: token.length, tokenPrefix: token.slice(0, 8), after, reqs };
}

